    /// <summary>
    /// Checks a match-code for an OAuth authorization request. If fails, then the authorization request has failed. Otherwise,
    /// authorization confirmation dialog must be shown and the link must be processed using acceptOauthRequest or declineOauthRequest
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> CheckOauthRequestMatchCodeAsync(string url = default, string matchCode = default)
    {

           using var activity =  StartCallActivity("CheckOauthRequestMatchCodeAsync", typeof(CheckOauthRequestMatchCode).FullName ?? "CheckOauthRequestMatchCodeAsync");

           try
           {
             return client.CheckOauthRequestMatchCodeAsync(url, matchCode);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
